def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import subprocess
    import sys

    if sys.platform != "win32":
        return cmd

    def get_interpreter_from_shebang(filepath):
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    return first_line[2:].split()[0]
        except Exception as e:
            print(f"Error reading shebang from {filepath}: {e}")
        return None

    if cmd:
        script_path = cmd[0]
        if os.path.isfile(script_path):
            interpreter = get_interpreter_from_shebang(script_path)
            if interpreter:
                # Check if the interpreter is a valid Windows path or a shebang interpreter
                if os.path.exists(interpreter):
                    # If the interpreter is a valid Windows path, prepend it to the command
                    return (interpreter, script_path) + cmd[1:]
                else:
                    # If it's not a valid path, it might be a shebang interpreter like '/usr/bin/env python'
                    # Replace it with the current Python interpreter
                    return (sys.executable, script_path) + cmd[1:]
    return cmd

