def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    from collections import defaultdict

    # Dictionary to hold the graph of dependencies
    graph = defaultdict(list)
    # Set to hold all unique items
    items = set()

    # Build graph
    for ordering in orderings:
        items.update(ordering)
        for i in range(len(ordering) - 1):
            graph[ordering[i]].append(ordering[i + 1])

    # Function to perform topological sort (Kahn's algorithm)
    def topological_sort(graph, items):
        in_degrees = {item: 0 for item in items}
        for u in graph:
            for v in graph[u]:
                in_degrees[v] += 1

        zero_in_degree = [item for item in in_degrees if in_degrees[item] == 0]
        sorted_order = []

        while zero_in_degree:
            u = zero_in_degree.pop(0)
            sorted_order.append(u)
            for v in graph[u]:
                in_degrees[v] -= 1
                if in_degrees[v] == 0:
                    zero_in_degree.append(v)

        if len(sorted_order) != len(items):
            raise ValueError("Cycle detected in the graph, cannot perform topological sort")

        return sorted_order

    try:
        return topological_sort(graph, items)
    except ValueError as e:
        raise ValueError("The provided orderings are invalid: " + str(e))

