def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimized = []

    def visit(cls):
        if cls in seen:
            return
        seen.add(cls)
        for base in cls.__bases__:
            visit(base)
        minimized.append(cls)

    for cls in reversed(classes):
        visit(cls)

    return list(reversed(minimized))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimized_bases = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            bases = set(cls.__bases__)
            # Remove any base that is already a subclass of another class in the list
            if not any(issubclass(b, cls) for b in classes if b is not cls):
                minimized_bases.append(cls)
    return minimized_bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        minimal = []
        for cls in classes:
            if all(not issubclass(cls, c) for c in minimal):
                to_remove = [c for c in minimal if issubclass(c, cls)]
                minimal = [c for c in minimal if c not in to_remove]
                minimal.append(cls)
        return minimal
    except TypeError as e:
        raise TypeError("All elements in classes must be class types") from e

