        minimal = []
        for cls in classes:
            if cls not in seen and all(not issubclass(c, cls) for c in classes if c is not cls):
                minimal.append(cls)
                seen.add(cls)
        return minimal
    except TypeError:
        raise TypeError("All elements in the list must be classes")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not all(isinstance(cls, type) for cls in classes):
        raise TypeError("All elements in the classes list must be classes")

    seen = set()
    minimal = []

    def add_bases(cls):
        for base in cls.__bases__:
            if base not in seen:
                seen.add(base)
                add_bases(base)
        minimal.append(cls)

    for cls in reversed(classes):
        if cls not in seen:
            seen.add(cls)
            add_bases(cls)

    return minimal[::-1]

