def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self._in_bounds(coord):
        return
    index = self._get_index(coord)
    self._counts[index] += weight

def _in_bounds(self, coord):
    return all(low <= x < high for x, (low, high) in zip(coord, zip(self._edges[:-1], self._edges[1:])))

def _get_index(self, coord):
    return tuple(np.searchsorted(self._edges[i], coord[i], side='right') - 1 for i in range(self._ndim))

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not hasattr(self, 'edges') or not hasattr(self, 'values'):
        raise AttributeError("Histogram instance must have 'edges' and 'values' attributes.")

    if coord < self.edges[0] or coord >= self.edges[-1]:
        return

    idx = np.searchsorted(self.edges, coord, side='right') - 1
    if 0 <= idx < len(self.values):
        self.values[idx] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self._valid_coordinate(coord):
        return  # Ignore coordinates outside the histogram edges

    # Find the bin indices for the coordinate
    bin_indices = tuple(
        np.searchsorted(edge, c, side='right') - 1
        for edge, c in zip(self._edges, coord)
    )

    # Ensure the bin indices are within the valid range
    if any(index < 0 or index >= len(edge) - 1 for edge, index in zip(self._edges, bin_indices)):
        return  # Ignore if any index is out of bounds

    # Increment the histogram at the bin indices with the given weight
    self._values[bin_indices] += weight

def _valid_coordinate(self, coord):
    """Check if the coordinate is within the histogram edges."""
    return all(edge[0] <= c <= edge[-1] for edge, c in zip(self._edges, coord))

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (self.edges[0] <= coord <= self.edges[-1]):
        return

    for i in range(len(self.edges) - 1):
        if self.edges[i] <= coord < self.edges[i + 1]:
            self.values[i] += weight
            break

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (self.edges[0][0] <= coord[0] <= self.edges[0][-1]) or not (self.edges[1][0] <= coord[1] <= self.edges[1][-1]):
        return

    x_idx = np.searchsorted(self.edges[0], coord[0], side='right') - 1
    y_idx = np.searchsorted(self.edges[1], coord[1], side='right') - 1

    if 0 <= x_idx < self.values.shape[0] and 0 <= y_idx < self.values.shape[1]:
        self.values[x_idx, y_idx] += weight

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """

    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
