            raise ValueError("Application is missing 'spec' or 'spec.manifest' attribute")

        for resource, manifest in app.spec.manifest.items():
            if resource not in app.spec.observers:
                # Generate a default observer schema for the resource
                default_observer = {
                    "resource": resource,
                    "attributes": ["status"]
                }
                if not app.spec.observers:
                    app.spec.observers = {}
                app.spec.observers[resource] = default_observer

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

