    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            xml_data = {}
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    base_name = os.path.basename(file_info.filename)
                    xml_content = z.read(file_info.filename).decode('utf-8')
                    if base_name in xml_data:
                        xml_data[base_name].append(xml_content)
                    else:
                        xml_data[base_name] = [xml_content]
            return xml_data
    except zipfile.BadZipFile:
        raise ValueError("The provided file is not a valid zip file")
    except FileNotFoundError:
        raise FileNotFoundError("The specified zip file does not exist")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

