def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, (list, tuple)):
        raise ValueError("args must be a list or tuple of expressions")

    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op = expr[0]
        left = expr[1]
        right = expr[2]

        # Absorption
        if op == '&' and isinstance(right, tuple) and len(right) == 3:
            if right[0] == '|' and right[1] == left:
                return left
            if right[0] == '|' and right[2] == left:
                return left
        if op == '|' and isinstance(right, tuple) and len(right) == 3:
            if right[0] == '&' and right[1] == left:
                return left
            if right[0] == '&' and right[2] == left:
                return left

        # Negative absorption
        if op == '&' and isinstance(right, tuple) and len(right) == 3:
            if right[0] == '|' and isinstance(right[1], tuple) and len(right[1]) == 3:
                if right[1][0] == '~' and right[1][1] == left:
                    return ('&', left, right[2])
            if right[0] == '|' and isinstance(right[2], tuple) and len(right[2]) == 3:
                if right[2][0] == '~' and right[2][1] == left:
                    return ('&', left, right[1])
        if op == '|' and isinstance(right, tuple) and len(right) == 3:
            if right[0] == '&' and isinstance(right[1], tuple) and len(right[1]) == 3:
                if right[1][0] == '~' and right[1][1] == left:
                    return ('|', left, right[2])
            if right[0] == '&' and isinstance(right[2], tuple) and len(right[2]) == 3:
                if right[2][0] == '~' and right[2][1] == left:
                    return ('|', left, right[1])

        return expr

    return [apply_absorption(expr) for expr in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def is_absorbable(expr1, expr2):
        if isinstance(expr1, tuple) and isinstance(expr2, tuple):
            op1, a1, b1 = expr1
            op2, a2, b2 = expr2
            if op1 == '&' and op2 == '|':
                return (a1 == a2 and b1 == ('~', a2)) or (a1 == b2 and b1 == ('~', a1))
            elif op1 == '|' and op2 == '&':
                return (a1 == a2 and b1 == ('~', a2)) or (a1 == b2 and b1 == ('~', a1))
        return False

    def absorb_expression(expr1, expr2):
        op1, a1, b1 = expr1
        op2, a2, b2 = expr2
        if (op1 == '&' and op2 == '|') or (op1 == '|' and op2 == '&'):
            if a1 == a2:
                return a1
            elif a1 == ('~', a2):
                return expr1 if op1 == '&' else expr2
            elif a2 == ('~', a1):
                return expr2 if op1 == '&' else expr1

    new_args = []
    i = 0
    while i < len(args):
        expr = args[i]
        if isinstance(expr, tuple):
            op, a, b = expr
            if (op == '&' and isinstance(b, tuple) and b[0] == '|') or \
               (op == '|' and isinstance(b, tuple) and b[0] == '&'):
                if is_absorbable(expr, b):
                    new_args.append(absorb_expression(expr, b))
                    i += 2  # Skip the next expression as it's absorbed
                    continue
            elif (op == '&' and isinstance(a, tuple) and a[0] == '|') or \
                 (op == '|' and isinstance(a, tuple) and a[0] == '&'):
                if is_absorbable(a, expr):
                    new_args.append(absorb_expression(a, expr))
                    i += 2  # Skip the next expression as it's absorbed
                    continue
        new_args.append(expr)
        i += 1

    return new_args

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt is None or not isinstance(dt, datetime):
        raise ValueError("dt must be a non-None datetime instance")

    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")

    # Convert to the target timezone
    target_dt = dt.astimezone(self)

    # Check for fold state
    fold_check = target_dt.replace(fold=1)
    if fold_check.utcoffset() != target_dt.utcoffset():
        return target_dt.replace(fold=1)
    else:
        return target_dt.replace(fold=0)

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    try:
        from dateutil.relativedelta import relativedelta

        # Extract all attributes from the relativedelta object
        attrs = [attr for attr in dir(self) if not attr.startswith('_') and not callable(getattr(self, attr))]

        # Normalize the values to integers
        normalized_values = {}
        for attr in attrs:
            value = getattr(self, attr)
            if not isinstance(value, int):
                if hasattr(value, 'denominator'):
                    # Handle fractions (like 1.5 days -> 1 day and 12 hours)
                    integer_part = int(value)
                    fractional_part = value - integer_part
                    if attr == 'days':
                        # Convert fractional days to hours
                        hours = int(fractional_part * 24)
                        if hours > 0:
                            normalized_values['hours'] = normalized_values.get('hours', 0) + hours
                else:
                    raise ValueError(f"Unexpected non-integer value for attribute {attr}: {value}")
            else:
                normalized_values[attr] = value

        # Return a new relativedelta object with normalized values
        return relativedelta(**normalized_values)

    except Exception as e:
        raise ValueError(f"Normalization failed: {str(e)}")

