                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    from collections import defaultdict
    from ruamel.yaml.nodes import MappingNode

    def merge_scalar(key, value, merged_dict):
        merged_dict[key] = value

    def merge_mapping(key, value, merged_dict):
        if key not in merged_dict:
            merged_dict[key] = defaultdict(list)
        for sub_key, sub_value in value.value:
            if isinstance(sub_value, MappingNode):
                merge_mapping(sub_key, sub_value, merged_dict[key])
            else:
                merge_scalar(sub_key, sub_value, merged_dict[key])

    merged_dict = defaultdict(dict)

    for key, value in nodes:
        if isinstance(value, MappingNode):
            merge_mapping(key, value, merged_dict)
        else:
            merge_scalar(key, value, merged_dict)

    result = []
    for key, value in merged_dict.items():
        if isinstance(value, dict):
            merged_value = []
            for sub_key, sub_value in value.items():
                if isinstance(sub_value, defaultdict):
                    merged_sub_value = [
                        (sub_sub_key, sub_sub_value) for sub_sub_key, sub_sub_value in sub_value.items()
                    ]
                    merged_value.append((sub_key, MappingNode(tag='tag:yaml.org,2002:map', value=merged_sub_value)))
                else:
                    merged_value.append((sub_key, sub_value))
            result.append((key, MappingNode(tag='tag:yaml.org,2002:map', value=merged_value)))
        else:
            result.append((key, value))

    return result

