                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            new_value = value1.value.copy()
            for key2, val2 in value2.value:
                key2_str = key2.value
                found = False
                for i, (key1, val1) in enumerate(new_value):
                    if key1.value == key2_str:
                        new_value[i] = (key1, merge_values(val1, val2))
                        found = True
                        break
                if not found:
                    new_value.append((key2, val2))
            return MappingNode(value1.tag, new_value, value1.start_mark, value1.end_mark)
        else:
            return value2

    merged_dict = {}
    for key, value in nodes:
        key_str = key.value
        if key_str in merged_dict:
            merged_dict[key_str] = merge_values(merged_dict[key_str], value)
        else:
            merged_dict[key_str] = value

    return [(ScalarNode(key.tag, key_str), value) for key_str, value in merged_dict.items()]

