            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    def merge(mapping_node1, mapping_node2):
        merged_dict = defaultdict(list)
        for key, value in mapping_node1.value:
            merged_dict[key.value].append(value)
        for key, value in mapping_node2.value:
            merged_dict[key.value].append(value)

        merged_value = []
        for key_value, values in merged_dict.items():
            last_value = values[-1]
            if all(isinstance(v, type(last_value)) for v in values):
                if isinstance(last_value, ruamel.yaml.nodes.MappingNode):
                    # Deep merge MappingNodes
                    merged_value.append(
                        (values[0], merge(values[0], last_value))
                    )
                else:
                    # Last value wins for non-MappingNodes
                    merged_value.append((values[0], last_value))
            else:
                # Last value wins in case of type conflict
                merged_value.append((values[0], last_value))
        return ruamel.yaml.nodes.MappingNode(tag=mapping_node1.tag, value=merged_value)

    merged_nodes = {}
    for key, value in nodes:
        if key.value in merged_nodes:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(merged_nodes[key.value], ruamel.yaml.nodes.MappingNode):
                merged_nodes[key.value] = merge(merged_nodes[key.value], value)
            else:
                merged_nodes[key.value] = value
        else:
