    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("The number must be a non-negative integer.")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("The alphabet must be a non-empty list of characters.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer or None.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters to form a valid base.")

    if number == 0:
        return alphabet[0] * padding if padding is not None else alphabet[0]

    result = []
    while number > 0:
        number, rem = divmod(number, base)
        result.append(alphabet[rem])

    result.reverse()

    if padding is not None:
        result = [alphabet[0]] * (padding - len(result)) + result

    return ''.join(result)

