def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # POSIX shell style splitting
        regex = re.compile(r"""(['"])(.*?)\1|\s+|(\S+)""")
    elif platform == 0:  # Windows/CMD
        # Naive approximation of CMD.EXE's behavior
        regex = re.compile(r"""(["'])(.*?)(\1)|\s+|(\S+)""")
    else:
        raise ValueError("Unsupported platform value. Use 'this', 0, or 1.")

    parts = []
    for match in regex.finditer(s):
        quoted, quoted_content, closing_quote, unquoted = match.groups()
        if quoted_content is not None:
            if quoted != closing_quote:
                raise ValueError("Mismatched quotes in command string.")
            parts.append(quoted_content)
        elif unquoted is not None:
            parts.append(unquoted)
    return parts

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
