def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    import os
    from pathlib import Path

    if not filename:
        filename = os.path.basename(archive_path)
    tmp_path = Path(tmp_path)
    extract_path = tmp_path / filename.rsplit('.', 1)[0]
    extract_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(extract_path)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(extract_path)], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(extract_path)], check=True)
        else:
            raise ValueError(f'Unsupported archive format for file: {archive_path}')
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f'Failed to extract archive {archive_path}: {e}')

    return f'file://{extract_path.resolve()}'

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    import os
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive file {archive_path} does not exist.")

    tmp_path = Path(tmp_path) / "repo"
    tmp_path.mkdir(parents=True, exist_ok=True)

    try:
        if filename is None:
            filename = os.path.basename(archive_path)
        repo_path = tmp_path / filename

        # Uncompress the archive
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzvf', archive_path, '-C', str(tmp_path)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjvf', archive_path, '-C', str(tmp_path)], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(tmp_path)], check=True)
        else:
            raise ValueError(f"Unsupported archive type for {archive_path}")

        # Return the file repo URL
        return f"file://{repo_path}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error extracting archive {archive_path}: {e}")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

