        raise ValueError(f"Cannot parse frequency: {frequency}")

    if unit.endswith('s'):
        unit = unit[:-1]

    if unit == 'second':
        return datetime.timedelta(seconds=amount)
    elif unit == 'minute':
        return datetime.timedelta(minutes=amount)
    elif unit == 'hour':
        return datetime.timedelta(hours=amount)
    elif unit == 'day':
        return datetime.timedelta(days=amount)
    elif unit == 'week':
        return datetime.timedelta(weeks=amount)
    elif unit == 'month':
        # Approximate month as 30 days
        return datetime.timedelta(days=30 * amount)
    elif unit == 'year':
        # Approximate year as 365 days
        return datetime.timedelta(days=365 * amount)
    else:
        raise ValueError(f"Unknown unit: {unit}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    import re
    match = re.match(r'(\d+)\s*(\w+)', frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number, unit = match.groups()
    number = int(number)
    unit = unit.lower()

    try:
        if unit in ('seconds', 'second', 'sec', 's'):
            return datetime.timedelta(seconds=number)
        elif unit in ('minutes', 'minute', 'min', 'm'):
            return datetime.timedelta(minutes=number)
        elif unit in ('hours', 'hour', 'hr', 'h'):
            return datetime.timedelta(hours=number)
        elif unit in ('days', 'day', 'd'):
            return datetime.timedelta(days=number)
        elif unit in ('weeks', 'week', 'w'):
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Cannot parse frequency: {frequency}") from e

