    if not isinstance(commands, list) or not isinstance(args, list):
        raise ValueError("Both commands and args must be lists.")

    full_command = commands + args

    try:
        if verbose:
            print("Running:", ' '.join(full_command))

        with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT) as process:
            output, error = process.communicate()

            if process.returncode != 0:
                if hide_stderr and error:
                    print("Error:", error.decode())
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output, stderr=error)

            if verbose and output:
                print("Output:", output.decode())

            return output.decode()

    except subprocess.CalledProcessError as e:
        raise ProgramError(f"Command {' '.join(e.cmd)} failed with return code {e.returncode}\nOutput: {e.output.decode()}\nError: {e.stderr.decode() if e.stderr else ''}") from e
    except Exception as e:
        raise ProgramError(f"An error occurred while running command: {' '.join(full_command)}\n{str(e)}") from e

