def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        if not isinstance(shape, tuple) or not all(isinstance(dim, int) and dim > 0 for dim in shape):
            raise ValueError("Shape must be a tuple of positive integers.")
        if not isinstance(dtype, np.dtype):
            raise TypeError("dtype must be a numpy.dtype object.")
        return np.empty(shape, dtype=dtype)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mean = 0.2
    sigma = 0.1
    try:
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((np.array(x) - mean) / sigma) ** 2)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import yaml
    from logging import LogRecord

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Configuration file not found: {filename}", args=(), exc_info=False))
            continue

        try:
            with open(filename, 'r') as file:
                config = yaml.safe_load(file)
        except Exception as e:
            log_records.append(LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Failed to parse configuration file: {filename}. Error: {str(e)}", args=(), exc_info=False))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        config_dict[filename] = {**config, **overrides}

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import toml
    import os

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Config file does not exist: {filename}", args=(), exc_info=False))
                continue

            with open(filename) as fd:
                raw_config = fd.read()
            config = toml.loads(raw_config)
            config_dict[filename] = config

        except Exception as e:
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error parsing config file {filename}: {str(e)}", args=(), exc_info=True))

    if overrides:
        for filename in overrides:
            if filename in config_dict:
                config_dict[filename].update(overrides[filename])

    if resolve_env:
        from dotenv import load_dotenv
        load_dotenv()
        for config in config_dict.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
                    env_var = os.getenv(value[2:-1])
                    if env_var is not None:
                        config[key] = env_var
                    else:
                        log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.WARNING, pathname=filename, lineno=0, msg=f"Environment variable {value[2:-1]} not found for key {key}", args=(), exc_info=False))

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import logging.config
    import toml

    if overrides is None:
        overrides = {}
    if not isinstance(config_filenames, (list, tuple)):
        raise ValueError("config_filenames must be a list or tuple")
    if not isinstance(overrides, dict):
        raise ValueError("overrides must be a dict")
    if not isinstance(resolve_env, bool):
        raise ValueError("resolve_env must be a boolean")

    configs = {}
    errors = []

    for filename in config_filenames:
        if not os.path.isfile(filename):
            errors.append(logging.LogRecord(name="config_loader", level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=(), exc_info=None))
            continue

        try:
            with open(filename) as fd:
                raw_config = fd.read()
            config = toml.loads(raw_config)

            # Apply overrides
            config.update(overrides)

            # Resolve environment variables if needed
            if resolve_env:
                config = _resolve_env_variables(config)

            configs[filename] = config
        except Exception as e:
            errors.append(logging.LogRecord(name="config_loader", level=logging.ERROR, pathname=filename, lineno=0, msg=f"Failed to parse config file: {e}", args=(), exc_info=True))

    return configs, errors

def _resolve_env_variables(config):
    import os
    if isinstance(config, dict):
        return {k: _resolve_env_variables(v) for k, v in config.items()}
    elif isinstance(config, list):
        return [_resolve_env_variables(v) for v in config]
    elif isinstance(config, str) and config.startswith('$'):
        return os.getenv(config[1:], config)
    return config

