@_validate_fromutc_inputs
def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("Input must be a timezone-aware datetime object.")

    # Check if the datetime is in a fold state
    try:
        dt_fold = dt.replace(fold=1)
    except TypeError:
        # Python version does not support fold attribute
        dt_fold = dt

    # If the original dt and dt_fold are the same, it's not in a fold state
    if dt_fold == dt:
        return self.localize(dt)

    # Determine if the original dt is in the first occurrence of the ambiguous datetime
    dt_first = self.localize(dt.replace(fold=0))
    dt_second = self.localize(dt.replace(fold=1))

    if dt == dt_first:
        return dt_first
    elif dt == dt_second:
        return dt_second
    else:
        raise ValueError("Input datetime does not match any occurrence of the ambiguous datetime.")

