            r'(?::\d+)?'  # optional port
            r'(?:/?|[/?]\S+)$', re.IGNORECASE)
        return re.match(regex, url) is not None

    def add_attributes(url):
        return f'<a href="{url}" target="_blank">{url}</a>'

    def replace_links(match):
        url = match.group(0)
        if is_valid_url(url):
            return add_attributes(url)
        return url

    try:
        import re
        return re.sub(r'https?://[^\s]+', replace_links, text)
