def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET
    from xml.parsers.expat import ExpatError

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try parsing as XML
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid XRD document")

            webfinger = {}
            for element in root:
                if element.tag.endswith('}Subject'):
                    webfinger['subject'] = element.text
                elif element.tag.endswith('}Alias'):
                    webfinger['alias'] = element.text
                elif element.tag.endswith('}Link'):
                    rel = element.attrib.get('rel')
                    href = element.attrib.get('href')
                    if rel and href:
                        webfinger[rel] = href
            return webfinger
        except (ExpatError, ValueError):
            logger.warning("parse_diaspora_webfinger: Unable to parse document")
            return {}

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Attempt to parse as JSON
        data = json.loads(document)
        if "links" in data:
            hcard_url = next((link["href"] for link in data["links"] if link["rel"] == "http://microformats.org/profile/hcard"), None)
            return {"hcard_url": hcard_url}
    except json.JSONDecodeError:
        try:
            # Attempt to parse as XRD
            root = ET.fromstring(document)
            xrd_ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            hcard_url = root.find(".//xrd:Link[@rel='http://microformats.org/profile/hcard']", xrd_ns)
            return {"hcard_url": hcard_url.get("href")} if hcard_url is not None else {}
        except ET.ParseError:
            pass
    return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON
        parsed_data = json.loads(document)
        if "links" in parsed_data:
            return {link["rel"]: link["href"] for link in parsed_data["links"]}
    except (json.JSONDecodeError, TypeError, KeyError):
        # Fallback to parse as XRD
        try:
            root = ET.fromstring(document)
            subj = root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject")
            subject = subj.text if subj is not None else None
            links = {}
            for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    links[rel] = href
            return {"subject": subject, **links}
        except (ET.ParseError, AttributeError, TypeError):
            logger.warning("parse_diaspora_webfinger: unable to parse document as JSON or XRD")
            return {}
    return {}

