    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import logging

    logger = logging.getLogger(__name__)

    if not playbook_path or not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a non-empty string")

    command = ["ansible-playbook"]

    if verbose:
        command.append('-' + 'v' * min(int(verbose), 5))

    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dictionary")
        command.extend(['--extra-vars', ' '.join(f'{k}={v}' for k, v in extra_vars.items())])

    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dictionary")
        for k, v in ansible_args.items():
            if v is None:
                command.append(f'--{k}')
            else:
                command.extend([f'--{k}', str(v)])

    command.append(playbook_path)

    logger.debug("Executing Ansible command: %s", ' '.join(command))

    try:
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            logger.error("Ansible playbook execution failed: %s", stderr.decode())
            raise RuntimeError(f"Ansible reported an error: {stderr.decode()}")
        logger.info("Ansible playbook executed successfully")
        return stdout.decode()
    except Exception as e:
        logger.error("An error occurred while executing the playbook: %s", str(e))
        raise

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
