    except FileNotFoundError:
        raise RuntimeError("ansible-playbook not found. Please ensure Ansible is installed.")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook failed with return code {e.returncode}\nstdout:\n{e.stdout}\nstderr:\n{e.stderr}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

