def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        parser = self._parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for the command: {parser_name}")

    converted_values = {}
    for arg_name, arg_value in values_dict.items():
        try:
            arg = next(arg for action in parser._actions if action.dest == arg_name for arg in action.option_strings)
            arg_type = parser._option_string_actions[arg].type
            if arg_type is not None:
                converted_values[arg_name] = arg_type(arg_value)
            else:
                converted_values[arg_name] = arg_value
        except (StopIteration, TypeError):
            # If the argument is not found or type conversion fails, keep the original value
            converted_values[arg_name] = arg_value

    values_dict.update(converted_values)

def _convert_non_cli_args(self, parser_name, values_dict):
